#!/usr/bin/env node
/**
 * Copies Cesium's prebuilt static runtime (Workers/, Assets/, Widgets/,
 * ThirdParty/) out of node_modules and into public/cesium so the browser can
 * fetch them at `${CESIUM_BASE_URL}/...`. Cesium loads those files at runtime
 * by URL — a bundler cannot inline them — so they have to be served as plain
 * static assets. public/cesium is gitignored and regenerated by the
 * postinstall/prebuild hooks that call this script.
 *
 * Node fs (not a shell copy) so it works identically on Windows and CI.
 */
import { copyFileSync, cpSync, existsSync, mkdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "node_modules", "cesium", "Build", "Cesium");
const dest = join(root, "public", "cesium");

if (!existsSync(src)) {
  // Not an error: `postinstall` can run in environments where the optional
  // map stack was pruned. The globe degrades to the MapLibre renderer.
  console.warn("[cesium-assets] node_modules/cesium not found — skipping copy");
  process.exit(0);
}

rmSync(dest, { recursive: true, force: true });
mkdirSync(dest, { recursive: true });
for (const dir of ["Workers", "Assets", "Widgets", "ThirdParty"]) {
  const from = join(src, dir);
  if (existsSync(from)) cpSync(from, join(dest, dir), { recursive: true });
}

// The prebuilt UMD bundle itself. globe-map.tsx loads this by URL rather than
// importing the npm package: Cesium's inlined binary strings contain NUL
// escapes that the bundler re-emits inside template literals, which is a parse
// error that takes the entire chunk (and the page's hydration) down with it.
const umd = join(src, "Cesium.js");
if (existsSync(umd)) copyFileSync(umd, join(dest, "Cesium.js"));
console.log(`[cesium-assets] copied Cesium runtime -> ${dest}`);
